package br.com.orientec.backend.adapter.in.web.usuario;
import br.com.orientec.backend.adapter.out.persistence.entity.usuario.*;
import br.com.orientec.backend.adapter.out.persistence.repository.usuario.*;
import br.com.orientec.backend.application.service.usuario.*;
import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/usuarios") @PreAuthorize("hasAuthority('PERM_OS_CONTROLAR')") public class UsuarioAdminController { private final UsuarioAdminService s; public UsuarioAdminController(UsuarioAdminService s){this.s=s;} @GetMapping public List<Usuario> listar(){return s.listar();} @GetMapping("/{id}") public Usuario buscar(@PathVariable Long id){return s.buscar(id);} @PostMapping public Usuario criar(@RequestBody UsuarioAdminService.UsuarioRequest r){return s.criar(r);} @PutMapping("/{id}") public Usuario atualizar(@PathVariable Long id,@RequestBody UsuarioAdminService.UsuarioRequest r){return s.atualizar(id,r);} @DeleteMapping("/{id}") public void excluir(@PathVariable Long id){s.excluir(id);} @GetMapping("/{id}/permissoes") public Set<String> permissoes(@PathVariable Long id){return s.permissoes(id);} @PutMapping("/{id}/permissoes") public void permissoes(@PathVariable Long id,@RequestBody Set<Long> ids){s.substituirPermissoes(id,ids);} }
